255	    public void respond(@PathVariable("sheetId") String sheetId,
256	            @RequestParam(name = "asOf", required = false) String asOf, PoolStore store, SettingStore settings,
257	            PersonStore people, SheetStore sheets, ObjectResponse<List<PoolResponse>> response) {
258	        String sheet = sheetId.trim();
259	        LocalDate on = History.date(asOf);
260	        BigDecimal sheetPot = (on == null ? settings : settings.asOf(on)).pot(sheet);
261	        Map<Long, List<PoolStore.Member>> members = store.members(sheet, on);
