266	                .collect(Collectors.toSet());
267	        // each member pool to the pool it is a member of, and its share there
268	        Map<Long, Long> parents = new HashMap<>();
269	        members.forEach((poolId, ms) -> ms.stream().filter(m -> m.memberPoolId() != null)
270	                .forEach(m -> parents.put(m.memberPoolId(), poolId)));
271	        Map<Long, List<BigDecimal>> cuts = new HashMap<>();
272	        for (PoolStore.Pool p : pools) {
273	            cutsOf(p.id(), members, parents, held, sheetPot, cuts, 0);
274	        }
275	        response.send(pools.stream().map(p -> {
276	            List<PoolStore.Member> ms = members.getOrDefault(p.id(), List.of());
277	            List<BigDecimal> cs = cuts.get(p.id());
278	            List<PoolResponse.MemberResponse> shown = new ArrayList<>();
279	            for (int i = 0; i < ms.size(); i++) {
280	                PoolStore.Member m = ms.get(i);
281	                shown.add(new PoolResponse.MemberResponse(m.personId(), m.memberPoolId(), m.name(),
282	                        m.share().setScale(2).toPlainString(), m.retired(),
283	                        cs == null ? null : cs.get(i).toPlainString()));
284	            }
285	            BigDecimal total = total(ms);
286	            return new PoolResponse(p.id(), p.name(), shown, total.toPlainString(), total.compareTo(HUNDRED) == 0);
287	        }).toList());
