289	
290	    /** The total of the members' shares, a retired member's counting as 0.00. */
291	    private static BigDecimal total(List<PoolStore.Member> ms) {
292	        return ms.stream().filter(m -> !m.retired()).map(PoolStore.Member::share)
293	                .reduce(BigDecimal.ZERO, BigDecimal::add).setScale(2);
294	    }
