298	    private static List<BigDecimal> cutsOf(long poolId, Map<Long, List<PoolStore.Member>> members,
299	            Map<Long, Long> parents, Set<Long> held, BigDecimal sheetPot, Map<Long, List<BigDecimal>> cuts,
300	            int depth) {
301	        if (cuts.containsKey(poolId) || depth > members.size() + 1) {
302	            return cuts.get(poolId);
303	        }
304	        BigDecimal pot = sheetPot;
305	        Long parent = parents.get(poolId);
306	        if (parent != null) {
307	            List<BigDecimal> above = cutsOf(parent, members, parents, held, sheetPot, cuts, depth + 1);
308	            pot = null;
309	            List<PoolStore.Member> siblings = members.getOrDefault(parent, List.of());
310	            for (int i = 0; above != null && i < siblings.size(); i++) {
311	                if (Long.valueOf(poolId).equals(siblings.get(i).memberPoolId())) {
312	                    pot = above.get(i);
313	                }
314	            }
315	        }
316	        List<PoolStore.Member> ms = members.getOrDefault(poolId, List.of());
317	        List<BigDecimal> found = total(ms).compareTo(HUNDRED) == 0 && pot != null ? cuts(ms, held, pot) : null;
