325	     *  tie, so the cuts total exactly the pot. */
326	    private static List<BigDecimal> cuts(List<PoolStore.Member> ms, Set<Long> held, BigDecimal pot) {
327	        BigDecimal shares = ms.stream().filter(m -> hasCut(m, held)).map(PoolStore.Member::share)
328	                .reduce(BigDecimal.ZERO, BigDecimal::add);
329	        List<BigDecimal> cuts = new ArrayList<>();
330	        BigDecimal sum = BigDecimal.ZERO.setScale(2);
331	        int largest = -1;
332	        for (int i = 0; i < ms.size(); i++) {
333	            PoolStore.Member m = ms.get(i);
334	            boolean cut = hasCut(m, held) && shares.signum() > 0;
335	            BigDecimal c = cut ? pot.multiply(m.share()).divide(shares, 2, RoundingMode.HALF_EVEN)
