394	 *  with a share that is not a number of at most two decimals, more than 0.00 and at most 100.00. A member pool
395	 *  is refused when it is already a member of a pool, when it would contain the pool through any chain (or is
396	 *  the pool itself), or when the chain of pools would be more than three deep. */
397	public class ValidateMember {
398	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
399	    private static final int MAX_DEPTH = 3;
400	
401	    public void validate(@PathVariable("sheetId") String sheetId, @PathVariable("poolId") String poolId,
402	            @RequestBody MemberRequest request, Out<MemberInput> body, RoleStore roles, PoolStore pools,
403	            PersonStore people) throws InvalidSheetException {
404	        String sheet = sheetId.trim();
405	        String user = request == null || request.user() == null ? "" : request.user().trim();
406	        roles.refuseChange(sheet, user);
407	        PoolStore.Pool pool;
408	        try {
409	            pool = pools.find(sheet, Long.parseLong(poolId.trim()));
410	        } catch (NumberFormatException e) {
411	            pool = null;
412	        }
413	        if (pool == null) {
414	            throw new InvalidSheetException("No such pool");
415	        }
416	        PoolStore.Pool member = request == null || request.memberPoolId() == null ? null
417	                : pools.find(sheet, request.memberPoolId());
