419	            throw new InvalidSheetException("No such pool to add");
420	        }
421	        Person person = member != null || request == null || request.personId() == null ? null
422	                : people.find(sheet, request.personId());
423	        if (member == null && person == null) {
424	            throw new InvalidSheetException("A person is required");
425	        }
426	        String text = request.share() == null ? "" : request.share().trim();
427	        if (!text.matches("\\d+(\\.\\d{1,2})?")) {
428	            throw new InvalidSheetException("A share is a percent with at most two decimals");
429	        }
430	        BigDecimal share = new BigDecimal(text).setScale(2);
431	        if (share.signum() <= 0 || share.compareTo(HUNDRED) > 0) {
432	            throw new InvalidSheetException("A share is more than 0.00 and at most 100.00");
433	        }
434	        if (member != null) {
435	            refuseNesting(sheet, pool, member, pools);
436	            body.set(new MemberInput(pool, null, member.id(), member.name(), share, user));
437	            return;
438	        }
439	        if (pools.isMember(pool.id(), person.getId())) {
440	            throw new InvalidSheetException(person.getName() + " is already in " + pool.name());
441	        }
442	        body.set(new MemberInput(pool, person.getId(), null, person.getName(), share, user));
