449	        }
450	        Map<Long, Long> parents = pools.parents(sheet);
451	        if (parents.containsKey(member.id())) {
452	            throw new InvalidSheetException(member.name() + " is already a member of a pool");
453	        }
454	        // the pools above the pool, counting it
455	        int above = 0;
456	        for (Long at = pool.id(); at != null; at = parents.get(at)) {
457	            if (at == member.id()) {
458	                throw new InvalidSheetException(member.name() + " already contains " + pool.name());
459	            }
460	            above++;
461	        }
462	        if (above + depth(member.id(), parents) > MAX_DEPTH) {
463	            throw new InvalidSheetException("A chain of pools is at most " + MAX_DEPTH + " deep");
464	        }
465	    }
